-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere 01_esquema.sql, 20_enemigos_zzz.sql, 04_personajes_zzz.sql y
-- 21_bangbus_zzz.sql.
--
-- Rotaciones actuales del contenido final de Zenless Zone Zero:
--   Defensa de Shiyu, nodo critico (hasta el 18 de septiembre): elementos
--     recomendados y enemigos de cada mitad de las fronteras 1 a 4 y de las
--     tres salas de la frontera 5, efectos de la fase y equipos recomendados.
--   Asalto mortal (hasta el 25 de septiembre): los tres jefes y el del modo
--     Adversidad, con sus debilidades, detalles, equipos con bangbu y los
--     beneficios que se pueden elegir.
--
-- Fuente: las guias de Game8. Los efectos estan traducidos del ingles (no son
-- los textos oficiales del juego) y los nombres de los beneficios del Asalto
-- mortal se dejan en ingles. Los enemigos que no tienen ficha se guardan solo
-- con su nombre.
--
-- Inserta lo que falte y actualiza lo que ya exista. Cuando cambie la rotacion
-- hay que volver a generar este archivo.
--
-- Generado el 2026-09-15.

insert into public.endgame_rotations (
  id, game_id, mode, name, status, begins_on, ends_on, effects, floors, extra
)
values
  ('zzz-shiyu-2026-09-04', 'zenless-zone-zero', 'shiyu-defense', 'Nodo crítico', 'actual', '2026-09-04', '2026-09-18', '[{"nombre":"Fronteras 1 a 4 y sala 1 de la frontera 5","descripcion":"El Daño etéreo y el Daño glacial de los agentes aumentan un 35 % y su Daño Crítico aumenta un 25 %.\nCuando un agente atacante golpea a un enemigo aturdido, la Defensa del enemigo se reduce un 25 % durante 5 s. Las activaciones repetidas reinician la duración.","tipo":"general"},{"nombre":"Frontera 5 · sala 2","descripcion":"Si en el equipo hay 2/3 agentes anómalos, el daño de Anomalía de Atributo que infligen los agentes aumenta un 10 %/60 % y todo el equipo obtiene 500/1500 dB al entrar en combate.","tipo":"general"},{"nombre":"Frontera 5 · sala 3","descripcion":"La Defensa de los agentes aumenta un 15 % y sus ataques ignoran un 20 % de la resistencia eléctrica de los enemigos.\nTras usar una técnica especial EX, la Probabilidad de Crítico del agente aumenta un 5 % y su Daño Crítico un 20 % durante 15 s. Las activaciones repetidas reinician la duración.","tipo":"general"}]'::jsonb, '[{"piso":1,"nombre":"Frontera 1","mitades":[{"nombre":"1.ª mitad","elementos":["Físico","Ígneo"],"oleadas":[["zzz-enemy-503","zzz-enemy-505","zzz-enemy-512","zzz-enemy-510"]],"equipos":[{"personajes":["zzz-remielle","zzz-alice","zzz-velina"],"bangbu":null},{"personajes":["zzz-starlight-billy","zzz-ju-fufu","zzz-lucia"],"bangbu":null},{"personajes":["zzz-lighter","zzz-evelyn","zzz-astra-yao"],"bangbu":null},{"personajes":["zzz-soukaku","zzz-ben","zzz-corin"],"bangbu":null}]},{"nombre":"2.ª mitad","elementos":["Etéreo","Glacial"],"oleadas":[["zzz-enemy-460","zzz-enemy-455","zzz-enemy-418","zzz-enemy-449"]],"equipos":[{"personajes":["zzz-norma","zzz-sigrid","zzz-sunna"],"bangbu":null},{"personajes":["zzz-miyabi","zzz-vivian","zzz-yuzuha"],"bangbu":null},{"personajes":["zzz-aria","zzz-nangong-yu","zzz-sunna"],"bangbu":null},{"personajes":["zzz-nicole","zzz-anby","zzz-pyrois"],"bangbu":null}]}]},{"piso":