s":[{"personajes":["zzz-sunna","zzz-dialyn","zzz-ye-shunguang"],"bangbu":null},{"personajes":["zzz-yuzuha","zzz-burnice","zzz-alice"],"bangbu":null},{"personajes":["zzz-starlight-billy","zzz-ju-fufu","zzz-lucia"],"bangbu":null},{"personajes":["zzz-pyrois","zzz-anby","zzz-nicole"],"bangbu":null}]},{"nombre":"2.ª mitad","elementos":["Ígneo","Glacial"],"oleadas":[["zzz-enemy-938"]],"equipos":[{"personajes":["zzz-sigrid","zzz-norma","zzz-astra-yao"],"bangbu":null},{"personajes":["zzz-lighter","zzz-lycaon","zzz-hugo"],"bangbu":null},{"personajes":["zzz-remielle","zzz-promeia","zzz-velina"],"bangbu":null},{"personajes":["zzz-corin","zzz-ben","zzz-soukaku"],"bangbu":null}]}]},{"piso":5,"nombre":"Frontera 5","mitades":[{"nombre":"Sala 1","elementos":["Etéreo","Glacial"],"oleadas":[["zzz-enemy-432","zzz-enemy-972","zzz-enemy-520","zzz-enemy-710"]],"equipos":[{"personajes":["zzz-sigrid","zzz-norma","zzz-sunna"],"bangbu":null},{"personajes":["zzz-lighter","zzz-lycaon","zzz-hugo"],"bangbu":null},{"personajes":["zzz-ellen","zzz-lycaon","zzz-zhao"],"bangbu":null},{"personajes":["zzz-norma","zzz-astra-yao","zzz-pyrois"],"bangbu":null}]},{"nombre":"Sala 2","elementos":["Glacial","Aéreo"],"oleadas":[["zzz-enemy-939","zzz-enemy-940","zzz-enemy-1132"]],"equipos":[{"personajes":["zzz-remielle","zzz-promeia","zzz-velina"],"bangbu":null},{"personajes":["zzz-miyabi","zzz-yanagi","zzz-yuzuha"],"bangbu":null},{"personajes":["zzz-jane-doe","zzz-caesar","zzz-burnice"],"bangbu":null},{"personajes":["zzz-alice","zzz-vivian","zzz-yuzuha"],"bangbu":null}]},{"nombre":"Sala 3","elementos":["Físico","Eléctrico"],"oleadas":[["zzz-enemy-511","zzz-enemy-918","zzz-enemy-919","zzz-enemy-1003"]],"equipos":[{"personajes":["zzz-cissia","zzz-trigger","zzz-seed"],"bangbu":null},{"personajes":["zzz-orphie-magus","zzz-soldier-0-anby","zzz-trigger"],"bangbu":null},{"personajes":["zzz-ye-shunguang","zzz-sunna","zzz-zhao"],"bangbu":null},{"personajes":["zzz-nekomata","zzz-dialyn","zzz-rina"],"bangbu":null}]}]}]'::jsonb, null),
  ('zzz-deadly-2026-09-11', 'zenless-zone-zero', 'deadly-assault', 'Asalto mortal', 'actual', '2026-09-11', '2026-09-25', '[{"nombre":"Sharp Rupture","descripcion":"La Tasa de Perforación de los agentes aumenta un 5 %. Al golpear a un enemigo, se ignora un 15 % de su resistencia eléctrica.\nTras usar una técnica especial o una técnica especial EX, el daño cortante aumenta un 20 % y la Defensa un 10 % durante 20 s. Las activaciones repetidas reinician la duración.","tipo":"elegible"},{"nombre":"Cinders of Corrosion","descripcion":"Si en el equipo hay 2/3 agentes anómalos, la Maestría de Anomalía de todo el equipo aumenta 20/60 ptos. y la acumulación de Anomalía aumenta un 10 %/20 %.\nTras provocar una Anomalía de Atributo a un enemigo, su Defensa se reduce un 10 % durante 10 s. Las activaciones repetidas reinician la duración.","tipo":"elegible"},{"nombre":"Gleaming Frost","descripcion":"Los agentes atacantes infligen un 20 % más de daño glacial.\nEl Daño Crítico de los agentes aumenta un 30 %. Al atacar a un enemigo aturdido, su multiplicador de aturdimiento aumenta un 20 % adicional durante 20 s. Las activaciones repetidas reinician la duración.","tipo":"elegible"}]'::jsonb, '[{"piso":1,"nombre":"Kusarikku","mitades":[{"nombre":null,"elementos":[],"debilidades":["Ígneo","Eléctrico"],"resistencias":["Glacial"],"oleadas":[["zzz-enemy-1207"]],"efectos":[{"nombre":"Detalles del combate","descripcion":"• Recomendado para agentes armeros.\n• El daño de Anomalía de Atributo que recibe Kusarikku se reduce un 40 %.\n• Contrarrestar su Asalto de fisura con un apoyo defensivo le aplica 1 acumulación de Expuesto, y aturdirlo le aplica 2. Cada acumulación aumenta un 10 % el daño de laceración que recibe, hasta 4 acumulaciones, durante 30 s. Las activaciones repetidas reinician la duración.\n• Tras activar su barrera corruptiva, contrarrestar su Asalto de fisura con un apoyo defensivo y debilitarlo da 1000 puntos; cada contraataque con apoyo defensivo da 700; anular su técnica de control da 2000. Se pueden conseguir hasta 5000 puntos.","tipo":"general"}],"equipos":[{"personajes":["zzz-claret","zzz-norma","zzz-rina"],"bangbu":"zzz-bangboo-1107","buff":"Sharp Rupture"},{"personajes":["zzz-soldier-0-anby","zzz-trigger","zzz-orphie-magus"],"bangbu":"zzz-bangboo-911","buff":"Gleaming Frost"},{"personajes":["zzz-trigger","zzz-cissia","zzz-seed"],"bangbu":"zzz-bangboo-110","buff":"Gleaming Frost"},{"personajes":["zzz-astra-yao","zzz-evelyn","zzz-norma"],"bangbu":"zzz-bangboo-592","buff":"Gleaming Frost"}]}]},{"piso":2,"nombre":"Girtablilu: estancación aberrante","mitades":[{"nombre":null,"elementos":[],"debilidades":[],"resistencias":[],"oleadas":[["zzz-enemy-1182"]],"efectos":[{"nombre":"Detalles del combate","descripcion":"• Recomendado para agentes anómalos.\n• Al provocar una Anomalía de Atributo a un enemigo, este obtiene 1 acumulación de Marca de plaga de ese atributo durante 30 s, hasta 2 acumulaciones. Repetir la del mismo atributo reinicia su duración.\n• Cada acumulación de Marca de plaga aumenta un 8 % el daño de Anomalía de Atributo que recibe el enemigo y un 8 % el daño que recibe su barrera corruptiva.\n• Al debilitar a un enemigo o anular su técnica, la Maestría de Anomalía de todo el equipo aumenta 60 ptos. durante 30 s. Las activaciones repetidas reinician la duración.\n• Debilitarlo da 1000 puntos; cada técnica de control contrarrestada da 500; impedir que complete la carga de su barrera corruptiva y debilitarlo da 1500. Si durante la técnica de control se anula con un contraataque de apoyo, se obtienen los puntos que queden de esa técnica. Se pueden conseguir hasta 5000 puntos.","tipo":"general"}],"equipos":[{"personajes":["zzz-remielle","zzz-jane-doe","zzz-velina"],"bangbu":"zzz-bangboo-1175","buff":"Cinders of Corrosion"},{"personajes":["zzz-promeia","zzz-vivian","zzz-yuzuha"],"bangbu":"zzz-bangboo-708","buff":"Cinders of Corrosion"},{"personajes":["zzz-aria","zzz-nangong-yu","zzz-sunna"],"bangbu":"zzz-bangboo-1016","buff":"Cinders of Corrosion"},{"personajes":["zzz-miyabi","zzz-yanagi","zzz-astra-yao"],"bangbu":"zzz-bangboo-542","buff":"Cinders of Corrosion"}]}]},{"piso":3,"nombre":"Ye Shiyuan, el siervo","mitades":[{"nombre":null,"elementos":[],"debilidades":["Glacial","Físico","Aéreo"],"resistencias":["Eléctrico"],"oleadas":[["zzz-enemy-975"]],"efectos":[{"nombre":"Detalles del combate","descripcion":"• Recomendado para agentes aturdidores.\n• Cada vez que Sobek y el Siervo se turnan, el Siervo obtiene 1 acumulación de Contrato y de Autosacrificio, hasta 3. Cada Contrato aumenta un 15 % su resistencia a la acumulación de Anomalía de todos los atributos y cada Autosacrificio aumenta un 10 % su multiplicador de aturdimiento. Mientras está aturdido, el Daño Crítico que recibe aumenta un 50 %.\n• Debilitar a Sobek y al Siervo da 1500 puntos y derrotar a Sobek da 2000. Se pueden conseguir hasta 5000 puntos.","tipo":"general"}],"equipos":[{"personajes":["zzz-dialyn","zzz-zhao","zzz-ye-shunguang"],"bangbu":"zzz-bangboo-985","buff":"Gleaming Frost"},{"personajes":["zzz-sigrid","zzz-norma","zzz-lycaon"],"bangbu":"zzz-bangboo-1107","buff":"Gleaming Frost"},{"personajes":["zzz-yidhari","zzz-lycaon","zzz-lucia"],"bangbu":"zzz-bangboo-878","buff":"Gleaming Frost"},{"personajes":["zzz-nekomata","zzz-dialyn","zzz-rina"],"bangbu":"zzz-bangboo-108","buff":"Gleaming Frost"}]}]},{"piso":4,"nombre":"Modo Adversidad · Faetón del Horizonte Calcinado integrado","mitades":[{"nombre":null,"elementos":[],"debilidades":["Eléctrico"],"resistencias":["Físico"],"oleadas":[["zzz-enemy-1208"]],"efectos":[{"nombre":"Detalles del combate","descripcion":"• Cuando el Faetón del Horizonte Calcinado integrado queda debilitado o se anula su técnica, el daño cortante de todo el equipo aumenta un 40 % durante 60 s. Las activaciones repetidas reinician la duración.\n• Cuando un agente golpea a un enemigo que no está aturdido, el Aturdimiento que inflige aumenta un 15 %. Mientras el jefe está aturdido, su multiplicador de aturdimiento aumenta un 20 %.\n• Mientras está en su estado de velo, contrarrestar su ataque con un apoyo defensivo y debilitarlo da 1500 puntos de puntuación; anular su técnica de control da 2000. Se pueden conseguir hasta 5000 puntos.","tipo":"general"}],"equipos":[{"personajes":["zzz-claret","zzz-norma","zzz-rina"],"bangbu":"zzz-bangboo-1107","buff":"Sharp Rupture"},{"personajes":["zzz-remielle","zzz-promeia","zzz-velina"],"bangbu":"zzz-bangboo-1175","buff":"Cinders of Corrosion"},{"personajes":["zzz-norma","zzz-sunna","zzz-sigrid"],"bangbu":"zzz-bangboo-1107","buff":"Gleaming Frost"},{"personajes":["zzz-seed","zzz-trigger","zzz-cissia"],"bangbu":"zzz-bangboo-911","buff":"Gleaming Frost"}]}]}]'::jsonb, null)
on conflict (id) do update
  set game_id = excluded.game_id,
      mode = excluded.mode,
      name = excluded.name,
      status = excluded.status,
      begins_on = excluded.begins_on,
      ends_on = excluded.ends_on,
      effects = excluded.effects,
      floors = excluded.floors,
      extra = excluded.extra,
      updated_at = now();

-- Las rotaciones que ya no son la actual dejan de ensenarse.
update public.endgame_rotations
set status = 'pasada', updated_at = now()
where game_id = 'zenless-zone-zero'
  and id not in ('zzz-shiyu-2026-09-04', 'zzz-deadly-2026-09-11');

-- Comprobacion
select mode, name, status, begins_on, ends_on, jsonb_array_length(floors) as pisos
from public.endgame_rotations
where game_id = 'zenless-zone-zero' and status <> 'pasada'
order by mode;
